const G=window.WalkGame,view=document.getElementById('view'),restart=document.getElementById('restart');
let state=null,phase='intro',prediction=null,snapshots=[],seed=0,mode='checking',requestVersion=0,lastAction=null;
const modeReady=fetch('/api/status').then(r=>r.ok?r.json():null).then(x=>{mode=x?.ready?'gemini':'offline';return mode;}).catch(()=>{mode='offline';return mode;});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function show(html){view.innerHTML=html;view.focus({preventScroll:true});window.scrollTo(0,0);}
function intro(){requestVersion++;phase='intro';state=null;snapshots=[];restart.hidden=true;show('<p class="eyebrow">English · Text prototype 0.4</p><h1>On the Same Bus</h1><p class="lead">A night bus. Four stops to go.</p><p class="muted">At some moments, choose an interpretation before you act.<br>It is a guess, not an answer. The stranger cannot hear it.</p><button class="primary" data-do="start">Get on</button><p class="muted"><span id="mode-label">'+(mode==='gemini'?'Gemini connected · Only observable actions are shared':mode==='offline'?'Offline demo · Local model service is not connected':'Checking the local model connection…')+'</span></p>');}
async function start(){await modeReady;seed=Math.floor(Math.random()*3);state=G.initial(seed);snapshots=[];restart.hidden=false;await perform(null);}
function enter(){prediction=null;phase=state.pending.predictions.length?'interpret':'action';render();}
function render(){const q=state.pending,last=state.history.at(-1),choices=phase==='interpret'?q.predictions:q.actions;show(`${last?`<div class="previous"><span>Your last action</span><p>${esc(last.action.label)}</p></div>`:''}<p class="eyebrow">${String(state.turn+1).padStart(2,'0')} · ${esc(q.title)}</p><p class="scene-text">${esc(q.text)}</p><p class="npc-action">${esc(q.cue)}</p>${phase==='interpret'?'<h3>What do you think is happening?</h3>':prediction?`<div class="prediction"><span class="label">Your interpretation, for now</span><p>${esc(prediction.label)}</p><button class="minor" data-do="rethink">Change your interpretation</button></div><h3>What do you do?</h3>`:'<h3>What do you do?</h3>'}<div class="choices">${choices.map((c,i)=>`<button data-pick="${c.id}"><span class="key">${i+1}</span>${esc(c.label)}</button>`).join('')}</div>`);}
async function pick(id){if(phase==='interpret'){prediction=state.pending.predictions.find(x=>x.id===id);if(!prediction)return;phase='action';render();return;}if(phase==='action')await perform(id);}
async function perform(id){
 const before=state,p=prediction?.id??null,version=requestVersion;lastAction=id;
 phase='waiting';show('<p class="muted">Waiting for a response. This pause is outside the story.</p>');
 try{
  let reply=null;
  if(mode==='gemini'){
   const response=await fetch('/api/react',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(G.npcContext(before,id)),signal:AbortSignal.timeout(45000)});
   const data=await response.json();if(!response.ok)throw Error(data.error||'The response could not be completed.');reply=data.reply;
  }
  if(version!==requestVersion)return;
  if(id===null)state=G.applyOpening(before,reply);
  else{const next=G.step(before,p,id,reply);snapshots[before.turn]=before;state=next;}
 }catch(error){if(version!==requestVersion)return;phase='error';show('<h2>This moment has not advanced</h2><p>'+esc('The response could not be completed. This moment has not advanced. Please retry.')+'</p><div class="choices"><button data-do="retry">Retry this action</button>'+(id===null?'':'<button data-do="back-action">Back to your choices</button>')+'</div>');return;}
 state.done?ending():enter();
}
function ending(){phase='ending';show(`<p class="eyebrow">${state.ending.kind==='contact'?'A connection made':'Separate journeys'}</p><h1>${state.ending.kind==='contact'?'It ends here':'Without a word'}</h1><p class="lead">${esc(state.ending.text)}</p><p class="muted">This encounter ends here.</p><div class="choices"><button class="primary" data-do="recap">Look back at both sides</button><button data-do="restart">Start a new ride</button></div>`);}
function optionsList(xs,selected){return '<ul class="facts">'+xs.map(x=>`<li>${x.id===selected?'✓ ':''}${esc(x.text)}${x.id===selected?' <strong>Chosen</strong>':''}</li>`).join('')+'</ul>';}
function decision(r,nextAction){return `<p><strong>What he noticed</strong><br>${esc(r.observation||'He did not notice this action.')}</p><p><strong>The interpretation he chose</strong><br>${esc(r.interpretation.text)}</p><details><summary>The three interpretations available then</summary>${optionsList(r.interpretations,r.interpretation.id)}</details><p><strong>What he expected you to do next</strong><br>${esc(r.prediction.text)}</p><details><summary>The three predictions available then</summary>${optionsList(r.predictions,r.prediction.id)}</details><p><strong>The action he chose</strong><br>${esc(r.action)}</p><details><summary>The actions available then</summary>${optionsList(r.actionOptions,r.actionId)}</details><p><strong>Why he chose it</strong><br>${esc(r.reason)}</p><p class="muted">${nextAction?'What you actually did next: '+esc(nextAction):'The encounter ended before this prediction could be tested.'}</p>`;}
function record(e){return `<article class="record"><h3>${String(e.turn+1).padStart(2,'0')} · ${esc(e.title)}</h3><p class="muted">${esc(e.seen)}</p><div class="compare"><div><span class="label">Your side</span><p><strong>What you thought</strong><br>${esc(e.prediction?.label??'No interpretation was recorded at this moment.')}</p><p><strong>What you did</strong><br>${esc(e.action.label)}</p></div><div><span class="label">Then, his full turn</span>${decision(e.npc.after,state.history[e.turn+1]?.action.label)}</div></div>${e.departure?`<p>${esc(e.departure)}</p>`:''}<button class="revisit" data-revisit="${e.turn}">Return to this moment</button></article>`;}
function recap(){phase='recap';show(`<p class="eyebrow">One encounter · Alternating perspectives</p><h1>What each of you saw</h1><p class="muted">Your interpretation was never shared with him. These options were saved at the time. A check mark shows his actual choice.</p><article class="record"><h3>Opening: he sees you take a seat</h3>${decision(state.opening,state.history[0]?.action.label)}</article>${state.history.map(record).join('')}<div class="choices"><button data-do="download">Save the full record</button><button data-do="restart">Start a new ride</button></div>`);}
function revisit(n){if(phase!=='recap'||!snapshots[n])return;requestVersion++;state=snapshots[n];snapshots=snapshots.slice(0,n);enter();}
function download(){const blob=new Blob([JSON.stringify({version:G.VERSION,mode,seed,initialNpcFacts:state.profile,ending:state.ending,opening:state.opening,nodes:state.history},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='On the Same Bus-both-perspectives.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
view.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.pick)pick(b.dataset.pick);else if(b.dataset.revisit!==undefined)revisit(Number(b.dataset.revisit));else switch(b.dataset.do){case'start':start();break;case'retry':perform(lastAction);break;case'back-action':phase='action';render();break;case'rethink':phase='interpret';render();break;case'recap':recap();break;case'download':download();break;case'restart':intro();break;}});
document.addEventListener('keydown',e=>{if(!['interpret','action'].includes(phase)||e.repeat||e.metaKey||e.ctrlKey||e.altKey||!['1','2','3','4'].includes(e.key))return;const xs=phase==='interpret'?state.pending.predictions:state.pending.actions;const c=xs[Number(e.key)-1];if(c){e.preventDefault();pick(c.id);}});
restart.onclick=()=>{if(confirm('Clear this ride and start again?'))intro();};intro();

modeReady.then(()=>{const el=document.getElementById('mode-label');if(el)el.textContent=mode==='gemini'?'Gemini connected · Only observable actions are shared':'Offline demo · Local model service is not connected';});
